diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..1e65743 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,60 @@ export interface Record {
   warns: readonly string[];
 }

+function getSemanticFingerprint(text: string): string {
+  const concepts = new Set<string>();
+
+  // Extract semantic concepts from constraint text
+  const normalized = text.toLowerCase();
+
+  // Operational overhead cluster: ops, operational, manage, running, stateful service, always-on
+  if (/\bops\b|operational|operate|manage|running|stateful|always-on|someone has to operate|take on/i.test(text)) {
+    concepts.add('operational_overhead');
+  }
+
+  // Infrastructure cluster: infrastructure, service, component, tier
+  if (/infrastructure|service|component|tier/i.test(text)) {
+    concepts.add('new_infrastructure');
+  }
+
+  // Cache-specific cluster
+  if (/cache/i.test(text)) {
+    concepts.add('cache_service');
+  }
+
+  // Return sorted concepts as semantic signature
+  return Array.from(concepts).sort().join('|');
+}
+
 export const project = (records: readonly Record[]): string => {
-  const lines: string[] = [];
+  const deduped = new Map<string, { type: string; text: string }>();
+
+  // Collect all constraints with deduplication by semantic fingerprint
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const fingerprint = getSemanticFingerprint(entry);
+      if (!deduped.has(`ruledOut:${fingerprint}`)) {
+        deduped.set(`ruledOut:${fingerprint}`, { type: 'ruled out', text: entry });
+      }
+    }
+    for (const limit of record.limits) {
+      const fingerprint = getSemanticFingerprint(limit);
+      if (!deduped.has(`limit:${fingerprint}`)) {
+        deduped.set(`limit:${fingerprint}`, { type: 'limit', text: limit });
+      }
+    }
+    for (const warn of record.warns) {
+      const fingerprint = getSemanticFingerprint(warn);
+      if (!deduped.has(`warn:${fingerprint}`)) {
+        deduped.set(`warn:${fingerprint}`, { type: 'warn', text: warn });
+      }
+    }
+  }
+
+  // Format output, preserving insertion order
+  const lines: string[] = [];
+  for (const { type, text } of deduped.values()) {
+    lines.push(`- ${type}: ${text}`);
   }
   return lines.join("\n");
 };
